+static void
+check_close(double actual, double expected)
+{
+  assert(isfinite(actual));
+  assert(fabs(actual - expected) <= 1e-11 * fmax(fabs(expected), 1e-30));
+}
+
+int
+main(void)
+{
+  struct gk_mirror_ctx ctx = create_ctx();
+  assert(ctx.Bmag_midp > 0.53 && ctx.Bmag_midp < 0.54);
+  double beam_energy = 25000.0 * GKYL_ELEMENTARY_CHARGE;
+  double beam_speed = sqrt(beam_energy / ctx.mi);
+  double beam_mu = beam_energy / (2.0 * ctx.B_p);
+  double xn[3] = {0.0, beam_speed, beam_mu};
+  double value[1], positive[1];
+
+  // Both beams must peak at the specified amplitude at the midplane.
+  eval_f_ion_source(0.0, xn, value, &ctx);
+  check_close(value[0], 200.0);
+  xn[1] = -beam_speed;
+  eval_f_ion_source(0.0, xn, value, &ctx);
+  check_close(value[0], 200.0);
+
+  // Follow a constant-energy orbit away from the midplane.
+  xn[0] = 0.2;
+  double xc[3] = {ctx.psi_eval, 0.0, xn[0]}, bvec[3];
+  bfield_func(0.0, xc, bvec, &ctx);
+  double bmag = sqrt(bvec[0]*bvec[0] + bvec[1]*bvec[1] + bvec[2]*bvec[2]);
+  xn[1] = sqrt(beam_speed*beam_speed - 2.0*beam_mu*(bmag-ctx.Bmag_midp)/ctx.mi);
+  eval_f_ion_source(0.0, xn, value, &ctx);
+  check_close(value[0], 200.0);
+
+  for (int iz = -20; iz <= 20; ++iz) {
+    xn[0] = ctx.z_max * iz / 20.0;
+    xn[1] = beam_speed;
+    for (int imu = 0; imu <= 4; ++imu) {
+      xn[2] = ctx.mu_max_ion * imu / 4.0;
+      eval_f_ion_source(0.0, xn, value, &ctx);
+      assert(isfinite(value[0]) && value[0] >= 1e-20 && value[0] <= 200.0);
+      if (fabs(xn[0]) > ctx.Z_m) check_close(value[0], 1e-20);
+    }
+    initial_density(0.0, xn, value, &ctx);
+    check_close(value[0], 1e17);
+    initial_upar(0.0, xn, value, &ctx);
+    if (fabs(xn[0]) <= ctx.Z_m) assert(value[0] == 0.0);
+    else assert(value[0] * xn[0] > 0.0);
+  }
+  xn[0] = 1.5;
+  initial_upar(0.0, xn, positive, &ctx);
+  xn[0] = -xn[0];
+  initial_upar(0.0, xn, value, &ctx);
+  check_close(value[0], -positive[0]);
+  initial_temp_ion(0.0, xn, value, &ctx);
+  check_close(value[0], ctx.Ti0/10.0);
+  initial_temp_elc(0.0, xn, value, &ctx);
+  check_close(value[0], ctx.Te0);
+
+  // Both velocity maps must be monotone, span their physical bounds,
