+    double previous[2] = {-INFINITY, -INFINITY}, mapped[2];
+    for (int idx = 0; idx <= 1000; ++idx) {
+      double vc[2] = {-1.0 + 2.0*idx/1000.0, idx/1000.0};
+      maps[species](0.0, vc, mapped, &ctx);
+      assert(mapped[0] > previous[0] && mapped[1] > previous[1]);
+      if (idx == 0) {
+        check_close(mapped[0], -vmax[species]);
+        assert(mapped[1] == 0.0);
+      }
+      previous[0] = mapped[0];
+      previous[1] = mapped[1];
+    }
+    check_close(mapped[0], vmax[species]);
+    check_close(mapped[1], mumax[species]);
+  }
+  double vc_left[2] = {0.0, nextafter(0.2, 0.0)}, vc_right[2] = {0.0, 0.2};
+  double mapped_left[2], mapped_right[2];
+  mapc2p_vel_ion(0.0, vc_left, mapped_left, &ctx);
+  mapc2p_vel_ion(0.0, vc_right, mapped_right, &ctx);
+  check_close(mapped_left[1], mapped_right[1]);
